// src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useState } from "react";
import { getMe, login as loginSvc, logout as logoutSvc } from "../serv/auth.service";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [status, setStatus] = useState("idle"); // idle | loading | ready

  useEffect(() => {
    (async () => {
      setStatus("loading");
      try {
        const data = await getMe();
        setUser(data?.user ?? null);
      } catch {
        setUser(null);
      } finally {
        setStatus("ready");
      }
    })();
  }, []);

  async function login(credentials) {
    const data = await loginSvc(credentials);
    setUser(data?.user ?? null);
    return data;
  }

  async function logout() {
    await logoutSvc();
    setUser(null);
  }

  const isAuth = !!user;
  const hasRole = (role) => Array.isArray(user?.roles) && user.roles.includes(role);

  const value = { user, isAuth, status, login, logout, hasRole };
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}
